insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('17e5ea51-94a8-4084-bfd8-18b8a92f9ae9', 'fr', 'À quoi les femmes s’opposent-elles quand on les aborde en journée ?', '["Être abordées par des inconnus dans les lieux publics", "Des hommes qui interrompent leurs courses et leur quotidien", "Une intention amoureuse exprimée directement en journée", "Des approches qui ignorent leur confort et le respect"]'::jsonb, 'Le malaise vient des limites ignorées, pas du fait d’être abordée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c7c4962-c5cf-480e-94ba-1cc03443f821', 'fr', 'Tu remarques une femme qui feuillette des livres dans une librairie. Quelle approche la met à l’aise ?', '["Arriver derrière elle et lui toucher l’épaule", "Complimenter tout de suite son physique", "Attendre qu’elle te regarde en premier", "Entrer dans son champ de vision, sourire calmement, puis dire bonjour"]'::jsonb, 'Une approche visible, avec un sourire, montre du respect et évite l’effet de surprise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4f1937b7-4e35-4007-97d7-0ba51bfa30af', 'fr', 'Pourquoi le soir punit-il l’hésitation ?', '["Les femmes sont abordées sans arrêt, elles ont donc plus de choix", "Dans les lieux animés, l’attention change vite ; les ouvertures disparaissent rapidement", "L’alcool rend les gens plus impatients et moins indulgents", "D’autres hommes l’aborderont si tu n’agis pas vite"]'::jsonb, 'Le soir, tout change vite : le moindre délai transforme les signaux en occasions manquées.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9c6d0086-b465-4912-9e47-4cec5bc122f2', 'fr', 'Tu engages la conversation calmement, mais tu parles doucement dans un endroit bruyant. Résultat probable ?', '["Elle se penche vers toi", "L’échange paraît posé", "L’élan retombe", "L’attirance augmente"]'::jsonb, 'Une énergie basse, décalée par rapport au lieu, fait décrocher.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e4f60ca8-4125-463e-b6ce-3c84259813a8', 'fr', 'Elle commande au comptoir. Tu te places à côté d’elle pour commander. Elle te jette un regard. Que fais-tu ?', '["Commander d’abord, puis engager la conversation une fois que vous avez vos verres", "Attendre de voir si elle donne un autre signal", "Lui dire bonjour et commencer à lui parler"]'::jsonb, 'N’attends pas d’autres signaux ; le soir, un regard suffit pour te lancer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dbc9b59e-d2c5-4cb0-be94-f4bc54ea2bca', 'fr', 'Quel est le but quand tu abordes un groupe ?', '["Impressionner la femme qui t’intéresse pour te démarquer des autres", "Être accepté par tout le monde, puis porter ton attention sur elle", "Repérer le meneur du groupe et t’en faire un ami pour avoir son approbation", "Apporter assez pour que le groupe t’invite à le rejoindre"]'::jsonb, 'Tenir compte du groupe te donne sa permission ; inclus tout le monde avant de te concentrer sur elle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10add83c-809f-43e0-aa9a-31d38bfb3270', 'fr', 'Un groupe rit fort. Tu arrives avec une remarque calme et sérieuse. Que se passe-t-il ?', '["Le décalage d’énergie les fait décrocher", "Ils s’engagent profondément avec toi", "Ils apprécient ton authenticité", "La femme qui t’intéresse te prend à part"]'::jsonb, 'Un décalage d’énergie fait décrocher ; accorde-toi à leur enthousiasme pour garder le rythme.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2efcf135-1220-4266-bbc1-7828bea5592d', 'fr', 'Quel changement d’état d’esprit aide les hommes à aborder des groupes ?', '["Voir ses amies comme des alliées potentielles, pas comme des obstacles", "Partir du principe qu’un groupe est toujours plus difficile qu’une femme seule", "Te concentrer seulement sur le fait de l’impressionner elle d’abord"]'::jsonb, 'Quand le groupe se sent pris en compte, le lien avec elle devient plus facile.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4756728e-4c07-484b-a976-9eeb5814eca7', 'fr', 'Tu commences par « J’ai une question pour toi ». Elle lève les yeux, dans l’attente. Que signale sa réaction ?', '["De la politesse", "De la curiosité", "Une évaluation", "Un rejet"]'::jsonb, 'La curiosité marche parce qu’elle attire naturellement l’attention ; commence par quelque chose d’intrigant.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('28aa155d-35ca-4afd-abcc-bc4cb3e22a6d', 'fr', 'Qu’est-ce qui rend « J’ai besoin d’un avis féminin » efficace comme entrée en matière ?', '["Elle se sent valorisée et importante dans l’échange", "Ça crée de la curiosité sur le dilemme ou la question", "Les deux réponses ci-dessus"]'::jsonb, 'Ça marche parce que ça lui donne un rôle ; elle se sent incluse dès le départ.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7aa7c045-3cd0-4ffe-aa02-400edd9bc5b7', 'fr', 'Pourquoi les accroches qui éveillent la curiosité marchent-elles mieux que les questions directes ?', '["Elles déclenchent le besoin du cerveau de combler un manque d’information", "Elles apportent des réponses factuelles immédiates", "Elles lui donnent envie de savoir la suite"]'::jsonb, 'La curiosité crée une attraction psychologique plus forte que le désintérêt par défaut.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f40037b2-a636-4084-a804-c553ece3de6a', 'fr', 'Quel avantage ont les accroches par supposition au début ?', '["Elles montrent ta domination", "Elles l’impliquent tout de suite", "Elles cachent ton intention", "Elles réduisent le risque"]'::jsonb, 'Une supposition appelle une réponse et crée une implication immédiate.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3e974466-6524-42dc-a429-63bb8e831188', 'fr', 'Pourquoi une accroche comme « Toi, tu fais du pilates, non ? » l’implique-t-elle tout de suite ?', '["Elle montre que tu as remarqué sa condition physique", "Elle crée une implication immédiate : elle doit corriger ou confirmer", "Elle montre que tu t’y connais en sport et en santé"]'::jsonb, 'Une supposition appelle une réponse. Elle est tout de suite impliquée pour corriger ou confirmer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1874cbce-d4aa-44b1-ab88-ff0c2745d69f', 'fr', 'Pourquoi les accroches par supposition accrochent-elles mieux que les questions passe-partout ?', '["Elles la rendent curieuse de ta perception", "On peut y répondre en pilote automatique", "Elles demandent une confirmation ou une correction"]'::jsonb, 'Une supposition lui donne le sentiment d’être vue et suscite une implication immédiate.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e84223a-e094-4ee6-8da9-79cd89d634c7', 'fr', '« J’ai besoin d’un avis féminin » marche parce que :', '["ça la rend curieuse de savoir sur quoi tu as besoin d’un avis", "elle sent que son point de vue est valorisé et important", "ça présente les femmes comme ayant un regard particulier dont tu as besoin", "toutes les réponses ci-dessus"]'::jsonb, 'Ça crée de la curiosité, la valorise et présente le point de vue féminin comme précieux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc959e07-994f-4a1d-b948-b437f3e6f2b2', 'fr', 'Tu commences par un dilemme. Elle te donne une réponse détaillée. Que pourrais-tu faire ensuite ?', '["Mettre fin à l’échange", "Approuver entièrement", "Changer de sujet", "Rebondir sur ce qu’elle a dit"]'::jsonb, 'Rebondir sur sa réponse récompense son effort et garde l’élan.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7c800f82-c80b-490c-988f-e66f6100d311', 'fr', 'Quelles accroches valorisent son point de vue ?', '["« J’ai besoin d’un avis féminin »", "« Petite question pour toi »", "« Tu es très attirante »", "« Mon pote et moi, on débattait d’un truc »"]'::jsonb, 'Ces accroches lui donnent un rôle ; elle se sent incluse dès le départ.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('43b03548-630d-4716-8d45-71c89fa4a819', 'fr', 'Qu’est-ce qu’une limite de temps quand on aborde ?', '["Un délai que tu lui donnes pour répondre à ton approche", "Une technique pour créer de l’urgence et de la rareté dans l’échange", "Une phrase d’ouverture qui indique que tu vas bientôt repartir"]'::jsonb, 'Annoncer que tu ne vas pas rester longtemps réduit la pression ; fais-le dès le début.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cfb43838-50ce-4ae4-8c8a-722afd35d73a', 'fr', 'Quel est le but d’annoncer une limite de temps au début d’une approche ?', '["Contrôler l’échange en te présentant comme quelqu’un d’occupé", "Créer de la rareté pour qu’elle accorde plus de valeur à ton temps", "La mettre à l’aise en lui enlevant la pression d’un échange sans fin"]'::jsonb, 'Annoncer que tu ne vas pas rester longtemps réduit la pression ; fais-le dès le début.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66801814-05f0-417d-a387-606cb86e6cf9', 'fr', 'Tu abordes une femme dans un café. Que peux-tu dire en premier pour réduire la pression ?', '["Complimenter tout de suite son physique", "Dire que tu ne peux rester qu’une seconde", "Poser des questions personnelles et profondes", "Proposer d’aller ailleurs"]'::jsonb, 'Une limite de temps indique que tu vas bientôt partir, ce qui lui fait baisser la garde.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8993be7c-90eb-4430-96e6-83d657f55add', 'fr', 'Quels signes indiquent qu’il est temps de faire une fausse sortie ?', '["L’énergie est au plus haut, elle rit et elle est très impliquée", "La conversation vient de commencer, la complicité est encore en train de se créer", "Tu sens que l’énergie va plafonner ou retomber naturellement", "Vous parlez depuis exactement 10 minutes, quelle que soit l’énergie"]'::jsonb, 'Énergie au sommet ou plateau imminent : c’est le bon moment. Ce n’est pas une question de chrono arbitraire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c6866bb5-1e8c-4c24-9fa6-7ea784314163', 'fr', 'À quoi sert une fausse sortie ?', '["Créer un manque en partant avant que la conversation s’essouffle d’elle-même", "Montrer que tu as d’autres options : tu n’as pas besoin de tirer chaque seconde", "T’empêcher de glisser vers la recherche d’approbation", "Garantir qu’elle voudra forcément continuer plus tard"]'::jsonb, 'Créer un manque, montrer que tu as le choix, éviter la recherche d’approbation : voilà les bénéfices d’une fausse sortie.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d51f94a-3406-49fb-98ed-99beb074d2bf', 'fr', '« C’était sympa, je vais faire un petit tour. Je reviens te voir tout à l’heure. » Tu t’éloignes. Qu’est-ce que ça a créé ?', '["Le risque qu’elle perde tout intérêt ou rencontre quelqu’un d’autre pendant ton absence", "Une impression positive et inachevée, avec la curiosité de te voir revenir", "Une confusion : est-ce que tu t’intéresses vraiment à elle ?", "La preuve que tu n’es pas vraiment décidé à la séduire"]'::jsonb, 'Partir au sommet = un souvenir positif + un manque qui rend curieuse. Elle en veut plus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('30461b26-dac7-40f7-ae3f-bc7f90b1ebcb', 'fr', 'Quelle est la différence entre ne pas aborder et se faire rejeter ?', '["Le rejet fait plus mal sur le moment", "Ne pas aborder protège ton ego et ta confiance", "Le rejet te donne de l’expérience ; ne pas aborder ne te donne rien"]'::jsonb, 'Dans les deux cas, pas de lien, mais le rejet te donne de l’expérience pour les approches suivantes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('46975d8e-4143-4ea5-9c92-bde52c3bebad', 'fr', 'Quel est le pire résultat possible quand il s’agit d’aborder ?', '["Un refus poli", "Une courte conversation ratée", "Le regret de ne pas avoir agi", "Un silence gênant"]'::jsonb, 'Le regret d’une occasion manquée dure plus longtemps qu’un bref refus.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('05af8c26-1d5f-4746-bd8d-93ffa9ceb943', 'fr', 'Pourquoi un refus vaut-il mieux que ne pas aborder ?', '["Il garantit un regret durable", "Il apporte de l’expérience et des informations", "Il crée une possibilité de lien", "Il supprime toute incertitude"]'::jsonb, 'L’action ouvre des portes ; l’inaction les ferme à coup sûr.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3400a772-93ac-48a3-a167-060ae3d525d8', 'fr', 'Qu’est-ce qui est à l’origine de presque tous les liens dans la vie ?', '["Des centres d’intérêt communs", "Le bon moment", "La confiance en soi", "Quelqu’un qui parle en premier"]'::jsonb, 'Tous les liens commencent parce que quelqu’un fait le premier pas et parle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bf5ff661-2958-4e0d-ab57-b3ef0436b379', 'fr', 'Tu es à la soirée d’un ami et tu ne connais presque personne. Que pourrais-tu faire en premier ?', '["Rester silencieux dans un coin jusqu’à ce que quelqu’un vienne vers toi", "Demander à quelqu’un comment il connaît l’hôte", "Attendre la phrase d’accroche parfaite", "Partir tôt pour éviter la gêne"]'::jsonb, 'Parler en premier crée des occasions ; le silence n’en crée aucune.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('833fb7a5-48fa-44ca-bb33-3134723fc718', 'fr', 'À quoi peut mener le fait d’ouvrir la bouche ?', '["De nouvelles amitiés", "De nouvelles expériences", "Une réussite garantie", "Des occasions inattendues"]'::jsonb, 'Aller vers les autres ouvre l’accès à toutes sortes de résultats.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('588b3d53-613d-4e21-bdeb-77f6157427c7', 'fr', 'Pourquoi aborder avec curiosité plutôt qu’avec un objectif ?', '["La curiosité est plus discrète, l’objectif plus assuré", "La curiosité évite l’attirance, l’objectif la crée", "La curiosité découvre qui elle est, l’objectif cherche un résultat"]'::jsonb, 'La curiosité explore la personne. Un objectif cherche à en tirer un résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4003461a-b8aa-4eaa-b66f-3d5847986f38', 'fr', 'Tu remarques des autocollants d’Islande sur son ordinateur. Quelle accroche montre une vraie curiosité ?', '["« Salut, je t’ai trouvée mignonne et j’avais envie de te rencontrer. »", "« Je peux t’offrir un café ? »", "« Tu as l’air de beaucoup voyager. »", "« C’est un autocollant d’Islande ? J’y étais l’an dernier. »"]'::jsonb, 'Être curieux de ce qu’elle a vécu invite un vrai lien, sans arrière-pensée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d398047f-31f2-46cb-991f-abb7e05f231d', 'fr', 'Pourquoi aborder avec curiosité crée-t-il des liens plus forts qu’avec un objectif ?', '["Ça fait d’elle un objectif à atteindre", "Elle se sent intéressante et vue", "Ça enlève la pression d’obtenir un résultat", "Ça permet une conversation plus facile et plus authentique"]'::jsonb, 'La curiosité se concentre sur elle en tant que personne, ce qui favorise un lien naturel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7265d45c-cbbc-4d5e-8220-2d1c5fe793f2', 'fr', 'Pourquoi aborder paraît-il plus difficile quand on le fait rarement ?', '["L’enjeu paraît plus élevé", "Il y a moins de chances de réussir", "Le moment est moins bien choisi", "La peur augmente"]'::jsonb, 'Quand les approches sont rares, chacune pèse plus lourd et paraît plus intense.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('31e5395b-0177-4703-8182-44c9921a16fc', 'fr', 'Quelle erreur pousse les gens à aborder moins qu’ils ne le pourraient ?', '["Être dans de mauvais endroits", "Attendre les conditions idéales", "Être sur leur téléphone", "Le manque d’intérêt"]'::jsonb, 'Attendre des conditions parfaites réduit le nombre total d’occasions. Tu peux aborder n’importe quand.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('94b04aa8-e3ca-474a-af0c-4aac0238c9b5', 'fr', 'Quelles habitudes te maintiennent régulièrement en contact avec les autres ?', '["Parler à des inconnus tout au long de ta journée", "Voir chaque endroit comme un lieu où t’entraîner à créer du lien", "N’aborder que quand tu te sens totalement sûr de toi"]'::jsonb, 'Aller régulièrement vers les autres réduit la pression et rend les échanges plus faciles.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5cd29e03-754c-4a91-8b5a-132fe680704d', 'fr', 'À quoi sert la règle des trois secondes ?', '["Créer un sentiment d’urgence", "Éviter le rejet", "Peaufiner tes accroches", "Agir avant que la résistance ne s’installe"]'::jsonb, 'Agir vite empêche le doute de s’installer. Bouge dans les trois secondes après l’avoir remarquée.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('71a2b057-c0c3-49ae-a552-62426201f6c9', 'fr', 'Pourquoi attendre rend-il les approches plus difficiles ?', '["La peur se multiplie", "L’énergie baisse", "L’intérêt s’estompe", "L’attention se déplace"]'::jsonb, 'La peur augmente quand l’esprit a le temps d’imaginer la suite. Bouge vite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a8119be9-b1ef-4a0d-ab94-b3b7fdcf7ef2', 'fr', 'Tu repères une femme qui te plaît dans un bar et tu veux l’aborder. Que fais-tu ?', '["Commencer à préparer l’accroche parfaite", "Penser d’abord aux risques de rejet", "Aller vers elle dans les trois secondes", "Rester immobile jusqu’à ne plus avoir peur"]'::jsonb, 'Agis avant que l’analyse ne crée de la résistance et de l’hésitation.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50b60dd8-f15e-4fdb-bbb1-8651ce23d2c0', 'fr', 'Pourquoi lui bloquer le passage et les mouvements crée-t-il un malaise ?', '["Ça déclenche des réactions automatiques face à une menace", "Ça paraît impoli", "Ça montre ta domination"]'::jsonb, 'Le corps réagit à un espace restreint avant toute pensée consciente. Laisse-lui de l’espace.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('eddec612-c258-4098-80cf-80aed2555258', 'fr', 'Tu l’abordes et tu remarques qu’elle ne peut pas facilement bouger. Meilleur ajustement ?', '["Reculer et lui laisser de l’espace", "Parler plus vite", "La complimenter"]'::jsonb, 'Laisser de l’espace garde le système nerveux de l’autre détendu et réceptif.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('aea4811b-264d-435b-ab0a-4bcab3bc274a', 'fr', 'Quels choix favorisent une approche confortable ?', '["Rester visible", "Bloquer les sorties", "Te tenir trop près", "Lui laisser de la place pour bouger"]'::jsonb, 'Rester visible et laisser de l’espace gardent son système nerveux détendu et réceptif.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2e5b5d64-e126-4877-9449-ad662c2d047e', 'fr', 'Que transmet un corps détendu en mouvement, avant même de parler ?', '["De l’assurance, de l’aisance et une intention sans menace", "Une présence qui s’excuse ou qui menace", "Un besoin de validation immédiate", "Un désintérêt pour ce qui t’entoure"]'::jsonb, 'Un mouvement fluide et ouvert installe inconsciemment de bonnes bases.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9e26bd7a-b3cd-4d6e-af6b-4122066f80b5', 'fr', 'Tu marches vers elle d’un pas saccadé et hésitant. Meilleure chose à faire ?', '["Ralentir, relâcher les épaules et te poser avant de réduire la distance", "T’arrêter où tu es et l’interpeller de loin", "Garder ta démarche pour montrer ton authenticité et ton honnêteté"]'::jsonb, 'Un mouvement détendu transmet la sécurité et lui rend l’échange plus facile.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bdb5e4d4-24f8-4710-a0ac-91194b2f10a8', 'fr', 'Quelles façons de bouger réduisent le malaise pendant ton approche ?', '["Un pas régulier", "Un regard détendu sur ce qui t’entoure", "Des épaules bloquées", "Une posture droite"]'::jsonb, 'Un mouvement détendu transmet la sécurité et lui rend l’échange plus facile.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7bc72d1b-23c3-4183-b696-a4c0d69085b0', 'fr', 'Pourquoi un petit sourire et un regard avant d’aborder aident-ils ?', '["Ils montrent une intention amicale et lui laissent le temps de juger si elle est en sécurité", "Ils créent de l’attirance avant même que tu lui aies parlé", "Ils créent de l’attente et la rendent plus investie"]'::jsonb, 'Un petit sourire montre ta bienveillance, et le regard lui permet de te remarquer calmement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48a8252e-7d72-4d16-ac74-c694f14bde94', 'fr', 'Vos regards se croisent de part et d’autre de la pièce. Elle détourne vite les yeux. Meilleure réaction ?', '["Aborder quand même ; détourner vite le regard est souvent un réflexe, pas un rejet", "Attendre qu’elle te regarde à nouveau pour confirmer son intérêt", "Renoncer, puisqu’elle a clairement montré son désintérêt"]'::jsonb, 'Détourner vite le regard est souvent un réflexe, pas un rejet conscient ; aborde quand même.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('42ba6d8b-fdaa-43b8-8fda-ad92c655df6e', 'fr', 'Pourquoi un regard chaleureux tôt améliore-t-il la première impression ?', '["Il la prend au dépourvu pour plus d’impact", "Il lui laisse le temps d’une première évaluation de sécurité", "Il évite la surprise qui met sur la défensive", "Il montre une intention amicale avant ton arrivée"]'::jsonb, 'Être visible et chaleureux rend l’approche rassurante plutôt que brusque.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9cbb1c37-1c29-4754-8d5f-f95600cf8b0a', 'fr', 'Pourquoi les accroches indirectes réduisent-elles la pression pour elle ?', '["Elles ressemblent à une conversation normale", "Elles évitent l’attirance", "Elles lui permettent d’être attirée plus facilement"]'::jsonb, 'Les accroches indirectes paraissent ordinaires et naturelles, ce qui réduit la pression pour tous les deux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9d2e1560-b720-4464-8836-db55cf007d4a', 'fr', 'Tu es assis à côté d’elle dans un café. Quelle accroche indirecte peux-tu utiliser ?', '["Lui demander si elle est déjà venue ici et ce qui est bon", "Complimenter son physique", "Lui demander si elle est célibataire"]'::jsonb, 'Les accroches indirectes paraissent ordinaires et naturelles, ce qui réduit la pression pour tous les deux.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5033dee2-a2a9-45d9-b214-0035a1ff5a9f', 'fr', 'Vous attendez tous les deux un train en retard. Quelles accroches indirectes peux-tu utiliser ?', '["Complimenter un de ses vêtements", "Lui demander si elle sait quand le train arrive", "Te présenter et lui demander son prénom", "Faire une remarque sur le retard"]'::jsonb, 'Une situation partagée rend l’entrée en matière attendue et facile à suivre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('73629f15-ce28-4413-a2af-85b0b03c1ef2', 'fr', 'Qu’est-ce qu’une accroche directe ?', '["Commencer par une conversation légère pour tester son aisance", "Utiliser une conversation neutre pour créer de la complicité", "Dire clairement dès le départ ton attirance ou ton intention amoureuse"]'::jsonb, 'Les accroches directes lèvent l’ambiguïté en annonçant ton intention d’emblée. Elle sait pourquoi tu es là.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('adb1f5a5-29e7-4c3b-88a1-33da91269c81', 'fr', 'Tu la vois dans un bar et tu veux de la clarté rapidement. Meilleure accroche ?', '["Faire une remarque sur le bar", "Lui demander si elle vient souvent ici", "Plaisanter sur la foule", "Lui dire que tu avais envie de la rencontrer"]'::jsonb, 'Être direct évite les devinettes et va droit à l’intention.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b6195146-f317-46e7-b387-626cd480fe2b', 'fr', 'En boîte. Musique forte. Qu’est-ce qui fait marcher une accroche directe ici ?', '["Le dire avec calme et assurance, sans demander la permission", "T’excuser de l’interrompre, elle et ses amies", "Un regard posé et un langage corporel détendu"]'::jsonb, 'Une accroche directe perd sa force quand elle s’accompagne d’excuses au lieu d’assurance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('587818de-4443-410a-b2e6-4b7c30881359', 'fr', 'Que veut dire donner le ton ?', '["Gérer les signes d’attirance", "Mener le sujet, le rythme et l’énergie", "T’accorder à son humeur", "Éviter le rejet"]'::jsonb, 'Donner le ton, c’est mener le moment, pas y réagir.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6f2f6f50-a54c-4103-af26-fc4b7d7eb5a0', 'fr', 'Tu abordes une femme qui lit. Quelle accroche montre que tu es à ta place plutôt que de t’imposer ?', '["« Désolé de t’interrompre, mais tu lis quoi ? »", "« Il est bien, ce livre ? Ça fait un moment que je pense à le lire. »", "« Je ne veux pas te déranger, mais il fallait que je te dise bonjour. »"]'::jsonb, 'Une posture forte vient de l’assurance, pas de la permission ; engage la conversation sans t’excuser.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90f24790-0a2d-429f-8aff-e70a5e1589ec', 'fr', 'Qu’est-ce qui rend une accroche plus intéressante que ce qu’elle faisait avant ?', '["Elle est plus forte, plus audacieuse ou plus énergique que ce qui l’entoure", "Elle crée des déclencheurs émotionnels comme la curiosité, le jeu ou le sentiment d’être valorisée", "Elle aborde des sujets qui la passionnent, d’après ce que tu as observé"]'::jsonb, 'Les déclencheurs émotionnels comme le jeu et la curiosité rendent ton entrée captivante. Le volume, non.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ecc4789-34ea-4c3f-a98b-9f7ded7e80ca', 'fr', 'Pourquoi est-il important d’adapter ton volume au lieu ?', '["Pour éviter de crier", "Pour ne pas avoir à répéter", "Pour réduire les frictions dans l’échange", "Pour avoir une voix attirante"]'::jsonb, 'Les frictions apparaissent quand le volume n’est pas adapté ; ajuste-le pour que tout reste facile.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e12bb639-9fd1-465e-9e08-5cdeb7ccd65f', 'fr', 'Après ton accroche, elle se penche vers toi et dit : « Pardon, quoi ? » Meilleure réaction ?', '["Répéter la même phrase au même volume", "Parler plus vite pour finir ta phrase", "Te rapprocher dans son espace", "Adapter ton volume et répéter calmement"]'::jsonb, 'Adapte ton volume au lieu. S’ajuster compte plus que le contenu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e173f101-7036-4046-854b-556473b41c8b', 'fr', 'Qu’est-ce qui crée des frictions dans ta façon de parler ?', '["Parler trop bas pour être bien entendu dans le lieu", "Avoir une voix grave et résonnante", "Débiter tes mots sans respirer", "Mal articuler"]'::jsonb, 'Les frictions viennent d’une voix mal adaptée ; ajuste le volume, respire et articule.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3a6aa99-3aa6-471c-b81a-ea31d016cfb1', 'fr', 'Quel comportement reflète une vraie ouverture à l’échange ?', '["Sourire", "Un ton neutre", "Te poser des questions en retour", "Répondre à tes questions"]'::jsonb, 'Ses questions montrent qu’elle participe, pas seulement qu’elle est polie ; c’est un feu vert pour continuer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('100aee65-eee7-4907-899a-20d6b97820b1', 'fr', 'À quoi sert principalement la lecture des premiers signaux ?', '["À aller plus vite", "À éviter le rejet", "À rester respectueux", "À l’impressionner"]'::jsonb, 'Son confort passe en premier ; sers-toi des signaux pour décider de continuer ou de lever le pied.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('9745631b-e02b-44c5-8703-7cfda0ab734f', 'fr', 'Quels signes indiquent généralement de la politesse plutôt que de l’ouverture ?', '["Des sourires brefs", "Des réponses courtes", "Aucune question en retour", "Elle interrompt ce qu’elle faisait"]'::jsonb, 'La politesse maintient l’harmonie sans inviter à continuer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a1716c8d-11f9-4afa-b80c-5a108dce463e', 'fr', 'Quand tu ne sais pas à quel point elle est intéressée, quelle est la meilleure chose à faire ?', '["Continuer la conversation jusqu’à ce qu’elle se réchauffe", "Faire un geste clair qui lui permet de dire oui ou non facilement", "Poser plusieurs questions de relance pour la mettre à l’aise", "Attendre qu’elle fasse avancer les choses"]'::jsonb, 'Une phrase claire lève l’ambiguïté et révèle s’il s’agit d’intérêt ou de simple politesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ab5203db-096d-46a0-b56b-1b2011ec738e', 'fr', 'À quoi sert un seul geste clair pour confirmer son intérêt ?', '["À lever l’ambiguïté et lui offrir une porte de sortie facile", "À la convaincre de s’intéresser à toi", "À accélérer l’échange quelle que soit sa réaction"]'::jsonb, 'Une phrase claire lève l’ambiguïté et révèle s’il s’agit d’intérêt ou de simple politesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('450abadf-8d1e-486e-b76f-6d6eb4d366a0', 'fr', 'Après des signaux neutres, quelle phrase aide à clarifier son intérêt ?', '["« Ça te dirait qu’on prenne un café un autre jour ? »", "« Et tu fais quoi dans la vie ? »", "« Je te laisse reprendre ta journée. Tu as Instagram ? »", "« Tu es un peu difficile à cerner. »"]'::jsonb, 'Une phrase claire lève l’ambiguïté et révèle s’il s’agit d’intérêt ou de simple politesse.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d5b86928-0a71-456d-a08d-f5aaaa20bce3', 'fr', 'Que comprennent généralement les signaux d’ouverture ?', '["Un corps tourné vers toi et un sourire sincère", "Des questions en retour et une implication qui dure", "Des réponses courtes et un regard qui fuit", "Elle se penche vers toi ou te renvoie ton énergie"]'::jsonb, 'Une femme ouverte à l’échange montre dès le départ un comportement ouvert et impliqué.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3401c3d2-b41a-4191-b69d-0ad4a8292b16', 'fr', 'Bien lire les signaux aide parce que ça :', '["garde les échanges agréables", "évite de mettre la pression", "la rend plus charmeuse", "garantit l’attirance"]'::jsonb, 'Savoir s’ajuster protège son confort, pas le résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e069eb31-5232-4ac9-b7e0-bd4b26b8bd92', 'fr', 'Elle répond en un mot, détourne aussitôt le regard, le corps tourné ailleurs. Quel est son signal ?', '["Ouverture : elle est timide et il faut que tu insistes gentiment", "Politesse : elle hésite ; tente une dernière fois, puis réévalue", "Froideur : elle n’est pas dans l’échange ; pars proprement sans insister"]'::jsonb, 'Un langage corporel fermé pèse plus que les réponses ; recule et pars calmement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0251b9d5-9ecf-4f71-aad2-dfc93f31e392', 'fr', 'Quelles qualités rendent une accroche captivante ?', '["La pression", "La curiosité", "Le jeu", "Le mystère"]'::jsonb, 'Une entrée en matière marche le mieux quand elle intrigue, pas quand elle exige.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('02e3aec0-93e1-49e3-8801-5e138b373f07', 'fr', 'Qu’est-ce qui rend efficaces les meilleures accroches indirectes ?', '["Elles expriment clairement ton attirance", "Elles commentent le lieu ou quelque chose que tu observes", "Elles portent uniquement sur son physique", "Elles demandent un engagement tôt"]'::jsonb, 'Une situation partagée crée de l’aisance et un échange naturel.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0601d6e9-3b2f-4dab-8c82-816f101403cc', 'fr', 'Quels signaux t’indiquent de continuer à construire l’échange ?', '["Elle se tourne vers toi, pose des questions et garde un langage corporel ouvert", "Elle sourit, répond longuement et te renvoie la balle", "Ce sont tous des signaux d’ouverture"]'::jsonb, 'Ce sont tous des signaux d’ouverture : continue à construire.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('06c68907-301c-447a-b17d-47f93da821ac', 'fr', 'Quelle est la force d’une approche directe, où elle doit tout de suite se demander si tu lui plais ?', '["Les femmes respectent les hommes francs sur leurs intentions", "Une franchise assurée crée une première étincelle d’attirance", "Si elle est intéressée, tu t’épargnes tout le cinéma censé créer de la complicité"]'::jsonb, 'S’il y a déjà de l’intérêt, une accroche directe supprime les préliminaires et fait avancer les choses plus vite.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('073d5930-369f-4dd9-9245-c250f26097bc', 'fr', 'Pourquoi prend-on souvent la politesse pour de l’ouverture ?', '["Elle a l’air amicale", "Elle cache le malaise", "Elle est méprisante", "Elle retarde le refus"]'::jsonb, 'Une réponse polie peut cacher un désintérêt ; regarde si elle te renvoie la balle.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('08850c3a-5d7f-4d3c-923c-731d1e3f4644', 'fr', 'Elle répond « ouais » avec un sourire, mais continue de balayer la salle du regard pendant que tu parles. Comment tu interprètes ça ?', '["Ouverture : sourire veut dire intérêt", "Politesse : respectueuse, mais pas vraiment là", "Mitigé : distraite, mais curieuse", "Froideur : balayer la salle veut toujours dire rejet"]'::jsonb, 'Une attention partagée signale de la politesse, pas de l’implication.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0a2112a8-7aa5-4d33-8a7d-8b46d381ad1c', 'fr', 'Elle répond chaleureusement, mais regarde sans arrêt son téléphone. Ça veut sans doute dire quoi ?', '["Elle est nerveuse", "Elle te teste", "Elle est occupée ou décroche", "Elle veut que tu insistes"]'::jsonb, 'L’implication demande de l’attention ; quand elle manque, n’insiste pas.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0b567d7e-67fa-4529-a5cb-2a646b501ae0', 'fr', 'Elle est avec des amies dans un bar. Qu’est-ce qui décide si une accroche de groupe marche ?', '["L’accroche doit être intéressante et leur demander leur avis", "Ton assurance quand tu poses la question", "Ta façon de passer de la question à une conversation normale"]'::jsonb, 'Assure-toi que l’accroche est intéressante et demande au groupe de participer.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0d78b9e6-8caf-46a0-9c29-39a256ccdd34', 'fr', 'Qu’apporte vraiment le fait d’être direct ?', '["Ça montre des qualités attirantes", "Ça crée de l’attirance par l’honnêteté", "Elle n’a pas à décoder tes intentions", "Tu n’as pas à prétendre être là pour autre chose"]'::jsonb, 'Les accroches directes lèvent l’ambiguïté en annonçant ton intention d’emblée. Elle sait pourquoi tu es là.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0dca33cf-d79b-4b24-88c0-4b19d5c03b2c', 'fr', 'Vous êtes tous les deux dans un parc à chiens à regarder les animaux jouer. Quelle accroche réduit la pression ?', '["« Ton chien est mignon, comme toi. »", "« On s’échange nos numéros ? »", "« Les chiens valent mieux que les gens. »", "« Il est de quelle race, le tien ? Le mien est toujours trop excité. »"]'::jsonb, 'Une expérience partagée sur le moment lance la conversation naturellement.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0e096470-35cf-4e08-bf03-85d6267ab373', 'fr', 'Pourquoi la douleur du regret dure-t-elle plus longtemps que celle d’un refus ?', '["Ton cerveau te repasse les occasions manquées plus longtemps que les brefs refus", "Un refus clôt l’histoire ; le regret laisse des questions sans réponse indéfiniment", "Les deux réponses ci-dessus"]'::jsonb, 'Un refus clôt l’histoire, alors que le regret fait rejouer à l’esprit ce qui n’a jamais eu lieu.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('0f4f3084-9f90-4036-ae95-cc8c706eba49', 'fr', 'Pourquoi demander son avis à quelqu’un est-il plus captivant que la conversation de surface ?', '["Un avis demande une réponse plus longue", "Un avis paraît plus intelligent", "Demander son avis montre que son jugement compte", "Un avis paraît moins risqué qu’un compliment"]'::jsonb, 'Les gens s’illuminent quand leur point de vue compte. Se sentir valorisé crée de l’implication.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('10284be9-9647-41db-8f18-3dfa77d66507', 'fr', 'Où doit se poser ton regard pendant que tu t’approches ?', '["Un bref regard détendu, sans la fixer ni rester rivé sur elle", "Rivé sur elle pour montrer clairement ton intention et ton intérêt", "Un peu à côté d’elle pour ne pas paraître trop intense"]'::jsonb, 'Un bref regard montre que tu l’as remarquée sans mettre de pression.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14546a1d-9532-4604-b285-8494197100dd', 'fr', 'Quel est le but de bien choisir ton angle et ta distance d’approche ?', '["Supprimer les obstacles inutiles à son confort", "Montrer un maximum d’assurance en étant tout près", "La faire se sentir un peu menacée", "Garantir une attirance immédiate"]'::jsonb, 'Une entrée respectueuse lui permet d’échanger sans avoir à gérer un malaise.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('14dc2ce1-631c-4b7a-b151-4c74c34bb2a3', 'fr', 'En boîte. Vos regards se croisent à travers la salle. Elle sourit. Que fais-tu ?', '["Lui rendre son sourire et attendre de voir si elle vient vers toi", "Aller vers elle tout de suite", "Continuer à la regarder", "Attendre qu’elle soit mieux placée pour l’aborder"]'::jsonb, 'En boîte, la décision paie ; lance-toi dès que la fenêtre s’ouvre.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('152af858-f915-4ba0-97af-dcd17bde6c3a', 'fr', 'Pourquoi lire les signaux est-il important pour son confort ?', '["Ça t’empêche de franchir des limites qu’elle n’a pas ouvertes", "Respecter ses signaux montre que tu sais t’ajuster", "Continuer malgré des signaux polis ou froids la met mal à l’aise", "Toutes les réponses ci-dessus"]'::jsonb, 'Les signaux montrent ce qui est bienvenu ; suis-les pour ne pas franchir de limites qu’elle n’a pas ouvertes.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('16844e95-a04f-4bcf-a8af-c185f70db3c7', 'fr', 'Quelle façon de dire ruine une accroche directe ?', '["Un ton calme", "Un regard posé", "Une énergie assurée", "Une énergie d’excuse"]'::jsonb, 'Une accroche directe perd sa force quand elle s’accompagne d’excuses au lieu d’assurance.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('170329e0-190e-459a-8870-3da632ce2a7f', 'fr', 'Quels comportements montrent une approche guidée par la curiosité ?', '["Remarquer des détails et poser des questions dessus", "Profiter de la conversation sans penser à la suite", "Orienter vite l’échange vers ses coordonnées", "Laisser l’échange se faire sans forcer la direction"]'::jsonb, 'La curiosité reste présente et exploratrice. Un objectif saute directement au résultat.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('18168e30-017b-49fc-8902-92152cce90b8', 'fr', 'En boîte, avec la musique à fond, elle te regarde brièvement puis se retourne. Que fais-tu ?', '["Attendre un signe plus clair de son intérêt", "L’aborder avec une bonne énergie et un sourire", "Parler doucement pour ne pas déranger son groupe", "Abandonner et chercher quelqu’un d’autre"]'::jsonb, 'Le soir, une action rapide et assurée paie avant que l’attention se déplace.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
